std::vector<PolygonWithHoles2d> result;

// Convert input polygons to CGAL format
CGAL::Polygon_2<Kernel> cgal_p1, cgal_p2;
for (const auto& p : P1) {
    cgal_p1.push_back(Kernel::Point_2(p.x(), p.y()));
}
for (const auto& p : P2) {
    cgal_p2.push_back(Kernel::Point_2(p.x(), p.y()));
}

// Ensure polygons are simple and oriented correctly
if (!cgal_p1.is_simple() || !cgal_p2.is_simple()) {
    return result;
}
if (cgal_p1.orientation() != CGAL::COUNTERCLOCKWISE) {
    cgal_p1.reverse_orientation();
}
if (cgal_p2.orientation() != CGAL::COUNTERCLOCKWISE) {
    cgal_p2.reverse_orientation();
}

// Compute intersection using CGAL
std::list<CGAL::Polygon_with_holes_2<Kernel>> cgal_result;
CGAL::intersection(cgal_p1, cgal_p2, std::back_inserter(cgal_result));

// Convert CGAL result back to our format
for (const auto& pwh : cgal_result) {
    PolygonWithHoles2d polygon_with_holes;

    // Convert outer boundary
    Polygon2d outer;
    for (auto it = pwh.outer_boundary().vertices_begin(); it != pwh.outer_boundary().vertices_end(); ++it) {
        outer.emplace_back(it->x(), it->y());
    }
    polygon_with_holes.outer = std::move(outer);

    // Convert holes
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        Polygon2d hole;
        for (auto it = hit->vertices_begin(); it != hit->vertices_end(); ++it) {
            hole.emplace_back(it->x(), it->y());
        }
        polygon_with_holes.holes.push_back(std::move(hole));
    }

    result.push_back(std::move(polygon_with_holes));
}

return result;

